WITH назв AS (SELECT DISTINCT d.entity_name AS прогон, x[1] AS вопрос, l.line FROM project_documents d CROSS JOIN LATERAL regexp_split_to_table(d.content, E'\n') AS l(line) CROSS JOIN LATERAL regexp_matches(l.line, '(Q-[0-9]{2,4})', 'g') AS x WHERE d.project_id = $1 AND d.entity_kind = 'run') SELECT н.прогон || ' → ' || н.вопрос || ': журнал называет решение владельца, а вопрос всё ещё открыт' AS detail FROM назв н JOIN project_questions q ON q.project_id = $1 AND q.id = н.вопрос AND q.state = 'open' WHERE EXISTS (SELECT 1 FROM scheme($1) t WHERE t.role = 'word.decided-by-owner' AND н.line ~* t.value) AND true ORDER BY 1
